#!/usr/bin/env python3
"""Prepare, correctness-check, then run the parent-authorized queue ablation."""
import argparse, collections, difflib, hashlib, importlib.util, json, os, pathlib, statistics, subprocess, sys, time
sys.dont_write_bytecode = True
REPO = pathlib.Path('/root/.codex/worktrees/f396/medaka')
ROOT = pathlib.Path('/tmp/medaka-queue-ablation-dcd09a442')
BASE_COMMIT = 'dcd09a442850838ba56acb6fc426c9fed0234666'
MANIFEST = ROOT/'variants.json'
VARIANT_NAMES = ['baseline','candidate']
CUSTOM_ARMS = VARIANT_NAMES
BOEHM_ARMS = ['boehm_caller_inline','boehm_inline']
ARMS = CUSTOM_ARMS + BOEHM_ARMS
PROFILES = ['ephemeral','list','tree','mutation','atomic','mixed','sizes']
COUNTS = 5_000_000
NURSERIES = {'offset':262_136,'aligned':262_144}
REPEATS = 8

def load_runner():
    path=ROOT/'source/baseline/run.py'
    spec=importlib.util.spec_from_file_location('gc_run_dcd09a442',path)
    mod=importlib.util.module_from_spec(spec); spec.loader.exec_module(mod)
    mod.REPO=REPO
    return mod

def sha(path): return hashlib.sha256(path.read_bytes()).hexdigest()
def tree_hashes(source):
    return {p.name:sha(p) for p in sorted(source.iterdir()) if p.is_file()}
def manifest():
    if not MANIFEST.exists():
        raise SystemExit(f'waiting for implementer frozen sources: missing {MANIFEST}')
    data=json.loads(MANIFEST.read_text())
    paths={'baseline':ROOT/'source/baseline'}
    paths.update({name:pathlib.Path(data[name]).resolve() for name in VARIANT_NAMES[1:]})
    for name,path in paths.items():
        for req in ('gc.c','gc.h','workload.c'):
            if not (path/req).is_file(): raise SystemExit(f'{name}: missing {path/req}')
    return paths,data

def clean_env(): return {k:v for k,v in os.environ.items() if not k.startswith('GC_')}

def build_all():
    r=load_runner(); paths,_=manifest(); binaries={}; commands={}; source_hashes={}; adapter_hashes={}
    frozen=subprocess.run(['git','show',BASE_COMMIT+':test/gc_prototype/gc.c'],cwd=REPO,check=True,capture_output=True).stdout
    assert hashlib.sha256(frozen).hexdigest()==sha(paths['baseline']/'gc.c')
    for path in paths['baseline'].rglob('*'):
        if path.is_file() and path.name!='gc.c':
            assert path.read_bytes()==(paths['candidate']/path.relative_to(paths['baseline'])).read_bytes()
    for name in VARIANT_NAMES:
        builddir=ROOT/'build'/name; builddir.mkdir(parents=True,exist_ok=True)
        source=paths[name]; r.HERE=source; r.BUILD_COMMANDS={}
        region_hash=r.adapter(builddir)
        adapter_hashes[name]={'runtime_allocator_region_sha256':region_hash,'caller_inline_header_sha256':sha(builddir/'boehm_caller.h'),'boehm_adapter_source_sha256':sha(builddir/'boehm_adapter.c')}
        defines,boehm=r.BACKENDS['custom_AS']
        binaries[name]=r.build(builddir,'custom_AS',defines,boehm=boehm)
        commands[name]=r.BUILD_COMMANDS['custom_AS']
        source_hashes[name]=tree_hashes(source)
    # Build both Boehm references against the frozen baseline source; same generated adapter and static libgc.
    source=paths['baseline']; r.HERE=source
    builddir=ROOT/'build'/'boehm_reference'; builddir.mkdir(parents=True,exist_ok=True)
    region_hash=r.adapter(builddir)
    adapter_hashes['boehm_reference']={'runtime_allocator_region_sha256':region_hash,'caller_inline_header_sha256':sha(builddir/'boehm_caller.h'),'boehm_adapter_source_sha256':sha(builddir/'boehm_adapter.c')}
    for name in BOEHM_ARMS:
        r.BUILD_COMMANDS={}; defines,boehm=r.BACKENDS[name]
        binaries[name]=r.build(builddir,name,defines,boehm=boehm)
        commands[name]=r.BUILD_COMMANDS[name]
    if r.boehm_config().get('boehm_linkage') != 'static': raise SystemExit('static libgc archive unavailable; refusing comparator build')
    baseline_gc=(paths['baseline']/'gc.c').read_text().splitlines(keepends=True)
    patches={name:''.join(difflib.unified_diff(baseline_gc,(paths[name]/'gc.c').read_text().splitlines(keepends=True),fromfile='a/gc.c',tofile='b/gc.c')) for name in VARIANT_NAMES}
    meta={
        'git_head':subprocess.run(['git','rev-parse','HEAD'],cwd=REPO,check=True,text=True,capture_output=True).stdout.strip(),
        'baseline_commit':BASE_COMMIT,
        'source_paths':{n:str(p) for n,p in paths.items()},'source_sha256':source_hashes,
        'runner_sha256':sha(ROOT/'source/baseline/run.py'),
        'runtime_sha256':sha(REPO/'runtime/medaka_rt.c'),
        'build_commands':commands,'adapter_hashes':adapter_hashes,'variant_patches':{name:{'sha256':hashlib.sha256(patch.encode()).hexdigest(),'unified_diff':patch} for name,patch in patches.items()},'runner_source_sha256':sha(pathlib.Path(__file__)),'binary_sha256':{n:sha(p) for n,p in binaries.items()},
        'clang':subprocess.run(['clang','--version'],check=True,text=True,capture_output=True).stdout.splitlines()[0],
        'libgc':{k:(str(v) if isinstance(v,pathlib.Path) else v) for k,v in r.boehm_config().items()},
        'compile_contract':'run.py helper; -std=c11 -O2 -g -Wall -Wextra -Werror; separate translation units; no LTO; Boehm arms use static libgc',
    }
    (ROOT/'build-metadata.json').write_text(json.dumps(meta,indent=2,default=str)+'\n')
    return r,paths,binaries,meta

def correctness():
    r,paths,binaries,meta=build_all(); env=clean_env(); results={}; identities={}
    for arm,binary in binaries.items():
        r.run([str(binary),'--selftest'],env=env)
        results[arm]={'selftest':'passed','profiles':{}}
        for profile in PROFILES:
            row=json.loads(r.run([str(binary),profile,'1024','240'],env=env).stdout)
            results[arm]['profiles'][profile]=row
            identities.setdefault(profile,set()).add((row['allocations'],row['payload_bytes'],row['checksum']))
    checks={f'{p}_identity_equal_across_arms':len(identities[p])==1 for p in PROFILES}
    checks['all_selftests_pass']=all(v['selftest']=='passed' for v in results.values())
    dynamic={'elapsed_seconds','preparation_seconds','process_peak_rss_bytes'}
    checks['custom_small_counter_equality']=all(
        {k:v for k,v in results['baseline']['profiles'][p].items() if k not in dynamic}==
        {k:v for k,v in results['candidate']['profiles'][p].items() if k not in dynamic}
        for p in PROFILES)
    checks['all_small_profile_identities_match']=all(checks.values())
    payload={'status':'passed' if all(checks.values()) else 'failed','count':1024,'nursery_bytes':240,
             'profiles':PROFILES,'arms':results,'checks':checks,'build_metadata':meta}
    (ROOT/'correctness/result.json').write_text(json.dumps(payload,indent=2,default=str)+'\n')
    print(json.dumps({'correctness':payload['status'],'checks':checks,'path':str(ROOT/'correctness/result.json')}))
    if not all(checks.values()): raise SystemExit('small correctness mismatch')

def do_benchmark(label,nursery,go):
    if go!='parent-authorized-2026-10-12': raise SystemExit('timings disabled: requires parent go token')
    corr_path=ROOT/'correctness/result.json'
    if not corr_path.exists() or json.loads(corr_path.read_text())['status']!='passed': raise SystemExit('run correctness first')
    # Recreate runner context but consume already-built exact binary paths.
    r=load_runner(); paths,_=manifest(); meta=json.loads((ROOT/'build-metadata.json').read_text())
    binaries={name:ROOT/'build'/name/'custom_AS' for name in VARIANT_NAMES}
    binaries.update({name:ROOT/'build'/'boehm_reference'/name for name in BOEHM_ARMS})
    if {n:sha(p) for n,p in binaries.items()} != meta['binary_sha256']: raise SystemExit('binary hash changed since correctness')
    assert {name:tree_hashes(path) for name,path in paths.items()}==meta['source_sha256']
    assert sha(pathlib.Path(__file__))==meta['runner_source_sha256']
    out=REPO/f'test/gc_prototype/results/2026-10-12-queue-5m-{label}.jsonl'
    if out.exists(): raise SystemExit('refusing to replace prior timing evidence')
    env=clean_env(); orders={}; rows=[]; checks={}
    header={'kind':'header','experiment':'queue-fast-path-ablation','label':label,'git_head':meta['git_head'],'baseline_commit':BASE_COMMIT,
            'nursery_bytes':nursery,'count':COUNTS,'repeats':REPEATS,'arms':ARMS,'profiles':PROFILES,
            'source_paths':meta['source_paths'],'source_sha256':meta['source_sha256'],
            'runner_sha256':meta['runner_sha256'],'runtime_sha256':meta['runtime_sha256'],
            'build_commands':meta['build_commands'],'binary_sha256':meta['binary_sha256'],'clang':meta['clang'],'adapter_hashes':meta['adapter_hashes'],'variant_patches':meta['variant_patches'],'runner_source_sha256':meta['runner_source_sha256'],
            'environment_policy':'remove all inherited environment variables whose names start with GC_; inherit all others; no CPU affinity or explicit heap cap',
            'timing_boundary':'heap_init and prepare_workload/layout descriptor setup are outside elapsed_seconds. The timer starts immediately before workload() and stops after it returns; workload includes the profile allocation/store/traversal/checksum computation and final major_collect(). The checksum assertion, stats formatting, getrusage(), and heap_destroy() are outside the timed interval.',
            'libgc':meta['libgc'],'correctness_sha256':sha(corr_path),
            'schedule':'eight cyclic rotations; each arm occupies each of four positions twice per profile'}
    for profile in PROFILES:
        orders[profile]=[]; expected=None
        for repeat in range(REPEATS):
            offset=repeat % len(ARMS); order=ARMS[offset:]+ARMS[:offset]; orders[profile].append(order)
            for pos,arm in enumerate(order):
                row=json.loads(r.run([str(binaries[arm]),profile,str(COUNTS),str(nursery)],env=env).stdout)
                ident=(row['allocations'],row['payload_bytes'],row['checksum'])
                if expected is None: expected=ident
                if ident!=expected: raise AssertionError((profile,repeat,arm,ident,expected))
                rows.append({'backend':arm,'profile':profile,'repeat':repeat,'execution_position':pos,
                             'execution_order':order,'sample':row})
    # Validate balanced positions and per-profile, per-repeat cross-arm identities.
    checks['all_profiles_arms_repeats_present']=len(rows)==len(ARMS)*len(PROFILES)*REPEATS
    checks['positions_balanced']=all(sorted(x['execution_position'] for x in rows if x['backend']==a and x['profile']==p)==sorted(list(range(len(ARMS)))*(REPEATS//len(ARMS))) for a in ARMS for p in PROFILES)
    checks['order_records_match_rows']=all(row['execution_order'][row['execution_position']]==row['backend'] for row in rows)
    checks['allocation_payload_checksum_identity']=all(len({(x['sample']['allocations'],x['sample']['payload_bytes'],x['sample']['checksum']) for x in rows if x['profile']==p and x['repeat']==r0})==1 for p in PROFILES for r0 in range(REPEATS))
    dynamic={'elapsed_seconds','preparation_seconds','process_peak_rss_bytes'}
    stable=[]
    for p in PROFILES:
        for rep in range(REPEATS):
            sample_by={x['backend']:x['sample'] for x in rows if x['profile']==p and x['repeat']==rep}
            baseline=sample_by['baseline']
            keys=set().union(*(set(sample_by[a]) for a in CUSTOM_ARMS))-dynamic
            stable.append(all({k:v for k,v in sample_by[a].items() if k in keys}=={k:v for k,v in baseline.items() if k in keys} for a in CUSTOM_ARMS[1:]))
    checks['custom_counter_memory_copy_peak_stats_equal_all_56_comparisons_per_capacity']=len(stable)==len(PROFILES)*REPEATS and all(stable)
    checks['all_checks_pass']=all(checks.values())
    assert {name:tree_hashes(path) for name,path in paths.items()}==meta['source_sha256']
    header['checks']=checks
    out.write_text('\n'.join(json.dumps(x,separators=(',',':')) for x in [header,*rows])+'\n')
    print(json.dumps({'artifact':str(out),'sha256':sha(out),'checks':checks,'rows':len(rows)}))
    if not checks['all_checks_pass']: raise SystemExit('artifact validation failed')

def main():
    p=argparse.ArgumentParser(); p.add_argument('action',choices=['prepare','correctness','benchmark']); p.add_argument('--label',choices=list(NURSERIES)); p.add_argument('--go')
    a=p.parse_args()
    if a.action=='prepare':
        paths,data=manifest(); print(json.dumps({'status':'sources-ready','source_paths':{k:str(v) for k,v in paths.items()},'manifest':data}))
    elif a.action=='correctness': correctness()
    else:
        if a.label is None: p.error('benchmark requires --label offset|aligned')
        do_benchmark(a.label,NURSERIES[a.label],a.go)
if __name__=='__main__': main()

